import random, subprocess, sys, os

TYPES = ["i8", "i16", "i32", "<2 x i8>", "<4 x i16>"]

def width(t):
    return {"i8":8,"i16":16,"i32":32,"<2 x i8>":8,"<4 x i16>":16}[t]

def rnd_const(t, rng):
    w = width(t)
    # bias toward sparse masks
    style = rng.random()
    if style < 0.5:
        v = rng.randrange(1, 1 << w)
    elif style < 0.8:
        # few bits set
        bits = rng.sample(range(w), rng.randrange(1, 4))
        v = sum(1 << b for b in bits)
    else:
        v = (1 << w) - 1
    if t.startswith("<"):
        return "<%s %s, %s>" % (t[4:t.index('x')-1] if False else "i8" if t=="<2 x i8>" else "i16", v, v) if False else splat(t, v)
    return str(v)

def splat(t, v):
    if t == "<2 x i8>":
        return "<i8 %d, i8 %d>" % (v, v)
    if t == "<4 x i16>":
        return "<i16 %d, i16 %d, i16 %d, i16 %d>" % (v, v, v, v)
    return str(v)

def const(t, v):
    if t.startswith("<"):
        return splat(t, v)
    return str(v)

BINOPS = ["and", "or", "xor"]

def gen(rng):
    t = rng.choice(TYPES)
    w = width(t)
    nparams = rng.randrange(1, 4)
    params = ["p%d" % i for i in range(nparams)]
    vals = list(params)
    body = []
    n = rng.randrange(2, 7)
    for i in range(n):
        op = rng.choice(BINOPS + BINOPS + ["add", "sub", "mul", "shl", "lshr", "ashr"])
        if op in BINOPS + ["add", "sub", "mul"]:
            a = rng.choice(vals)
            if rng.random() < 0.75:
                b = const(t, rng.randrange(0, 1 << w) if rng.random() < 0.5 else rng.choice([1,2,3,4,7,8,15,16,24,31,63,127,128,255]))
            else:
                b = rng.choice(vals)
            flags = ""
            if op in ("add","sub","mul") and rng.random() < 0.3:
                flags = rng.choice([" nuw ", " nsw ", " nuw nsw "])
                body.append("  %%r%d = %s%s %s %s, %s" % (i, op, flags, t, a, b))
            else:
                body.append("  %%r%d = %s %s %s, %s" % (i, op, t, a, b))
            vals.append("r%d" % i)
        else:
            a = rng.choice(vals)
            sa = rng.randrange(0, w)
            flags = ""
            if op == "shl" and rng.random() < 0.3: flags = rng.choice([" nuw", " nsw"])
            if op in ("lshr","ashr") and rng.random() < 0.3: flags = " exact"
            body.append("  %%r%d = %s%s %s %s, %s" % (i, op, flags, t, a, const(t, sa)))
            vals.append("r%d" % i)
    # sinks
    sinks = []
    tgt = rng.choice(vals)
    k = rng.randrange(1, 3)
    for j in range(k):
        v = rng.choice(vals)
        style = rng.randrange(0, 6)
        if style == 0:
            sinks.append("  call void @use(%s %s)" % (t, v))
        elif style == 1:
            c = const(t, rng.choice([1,3,7,8,15,16,24,31,63,127,255]))
            sinks.append("  %%m%d = and %s %s, %s" % (j, t, v, c))
            sinks.append("  call void @use(%s %%m%d)" % (t, j))
        elif style == 2:
            c = const(t, rng.choice([1,3,7,8,15,16,31,63,127,255]))
            sinks.append("  %%s%d = lshr %s %s, %s" % (j, t, v, c))
            sinks.append("  call void @use(%s %%s%d)" % (t, j))
        elif style == 3:
            c = const(t, rng.choice([0,1,3,7,8,15,16,255]))
            sinks.append("  %%c%d = icmp eq %s %s, %s" % (j, t, v, c))
            sinks.append("  call void @llvm.assume(i1 %%c%d)" % j)
        elif style == 4:
            c = const(t, rng.choice([1,3,7,8,15,16,24,31,63,127,255]))
            sinks.append("  %%tr%d = trunc %s %s to i8" % (j, t, v))
            sinks.append("  call void @use8(i8 %%tr%d)" % j)
        else:
            sinks.append("  ret %s %s" % (t, v))
            break
    if not any(s.strip().startswith("ret") for s in sinks):
        sinks.append("  ret void")
    fn = "define void @f(%s) {\n" % ", ".join("%s %%%s" % (t, p) for p in params)
    fn += "\n".join(body) + "\n" + "\n".join(sinks) + "\n}\n"
    hdr = """declare void @use(%s)
declare void @use8(i8)
declare void @llvm.assume(i1 noundef)
""" % t
    return hdr + fn

def main():
