    N = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    for s in range(seed0, seed0 + N):
        rng = random.Random(s)
        ir = gen(rng)
        open("/tmp/w/f.ll", "w").write(ir)
        r = subprocess.run(["opt", "-S", "-passes=bdce", "/tmp/w/f.ll", "-o", "/tmp/w/f.out.ll"],
                           capture_output=True, text=True)
