            print("=== SEED %d: OPT CRASH ===" % s); print(ir); print(r.stderr[:2000]); return
        r = subprocess.run(["alive-tv", "/tmp/w/f.ll", "/tmp/w/f.out.ll"], capture_output=True, text=True)
        if "Transformation seems to be correct" not in r.stdout:
            print("=== SEED %d: PROBLEM ===" % s)
            print(ir)
            print(open("/tmp/w/f.out.ll").read())
            print(r.stdout[-3000:], r.stderr[-2000:])
            return
    print("no issues in range")

main()
