import random, subprocess, sys

TYPES = {"i8":8, "i16":16, "i32":32, "<2 x i8>":8, "<4 x i16>":16}

def splat(t, v):
    if t == "<2 x i8>":
        return "<i8 %d, i8 %d>" % (v, v)
    if t == "<4 x i16>":
        return "<i16 %d, i16 %d, i16 %d, i16 %d>" % (v, v, v, v)
    return str(v)

def const(t, v):
    return splat(t, v)

MASKS = [0,1,2,3,4,7,8,15,16,24,31,63,127,128,255]

def gen(rng):
    t = rng.choice(list(TYPES))
    w = TYPES[t]
    params = ["%%p%d" % i for i in range(rng.randrange(1, 4))]
    vals = list(params)
    body = []
    ctr = [0]
    def newval():
        ctr[0] += 1
        v = "%%r%d" % ctr[0]
        vals.append(v)
        return v
    for _ in range(rng.randrange(2, 8)):
        kind = rng.random()
        a = rng.choice(vals)
        if kind < 0.45:
            op = rng.choice(["and", "or", "xor"])
            b = const(t, rng.choice(MASKS + [rng.randrange(0, 1 << w)])) if rng.random() < 0.8 else rng.choice(vals)
            v = newval()
            body.append("  %s = %s %s %s, %s" % (v, op, t, a, b))
        elif kind < 0.62:
            op = rng.choice(["add", "sub", "mul"])
            fl = rng.choice(["", "", " nuw", " nsw", " nuw nsw"]) if op != "mul" else rng.choice(["", " llvm.assume"])
            fl = "" if fl == " llvm.assume" else fl
            b = const(t, rng.choice(MASKS)) if rng.random() < 0.6 else rng.choice(vals)
            v = newval()
            body.append("  %s = %s%s %s %s, %s" % (v, op, fl, t, a, b))
        elif kind < 0.78:
            op = rng.choice(["shl", "lshr", "ashr"])
            fl = rng.choice(["", "", " nuw", " nsw"]) if op == "shl" else rng.choice(["", "", " exact"])
            v = newval()
            body.append("  %s = %s%s %s %s, %s" % (v, op, fl, t, a, const(t, rng.randrange(0, w))))
        elif kind < 0.86:
            op = rng.choice(["cttz", "ctlz"])
            v = newval()
            body.append("  %s = call %s @llvm.%s.%s(%s %s, i1 false)" % (v, t, op, t.replace(" ","").replace("<","").replace(">","").replace("x",""), t, a))
        elif kind < 0.93:
            c = rng.choice(vals)
            v = newval()
            body.append("  %s = select i1 %%p0, %s %s, %s %s" % (v, t, a, t, c))
        else:
            v = newval()
            body.append("  %s = and %s %s, %s" % (v, t, a, const(t, rng.choice(MASKS))))
    # condition values for select need i1; add one
    sinks = []
    for _ in range(rng.randrange(1, 3)):
        v = rng.choice(vals)
        style = rng.randrange(0, 7)
        if style == 0:
            sinks.append("  call void @use_%s(%s %s)" % (t.replace("<","").replace(">","").replace(" ","").replace("x","x"), t, v))
        elif style == 1:
            sinks.append("  %%s1 = and %s %s, %s" % (t, v, const(t, rng.choice(MASKS))))
            sinks.append("  call void @use_%s(%s %%s1)" % (t.replace("<","").replace(">","").replace(" ","").replace("x","x"), t))
        elif style == 2:
            sinks.append("  %%s2 = lshr %s %s, %s" % (t, v, const(t, rng.randrange(1, w))))
            sinks.append("  call void @use_%s(%s %%s2)" % (t.replace("<","").replace(">","").replace(" ","").replace("x","x"), t))
        elif style == 3:
            sinks.append("  %%s3 = icmp ugt %s %s, %s" % (t, v, const(t, rng.choice(MASKS))))
            sinks.append("  call void @llvm.assume(i1 %%s3)")
        elif style == 4:
            sinks.append("  %%s4 = trunc %s %s to i8" % (t, v))
            sinks.append("  call void @use_i8(i8 %%s4)")
        elif style == 5:
            sinks.append("  store %s %s, ptr @g" % (t, v))
        else:
            sinks.append("  %%s6 = mul %s %s, %s" % (t, v, const(t, rng.choice(MASKS))))
            sinks.append("  call void @use_%s(%s %%s6)" % (t.replace("<","").replace(">","").replace(" ","").replace("x","x"), t))
    sinks.append("  ret void")
    uses = set()
    for s in sinks:
        for tt in TYPES:
            if ("use_%s(" % tt.replace("<","").replace(">","").replace(" ","").replace("x","x")) in s:
                uses.add(tt)
    hdr = "declare void @llvm.assume(i1 noundef)\ndeclare void @use_i8(i8)\n@g = global i64 zeroinitializer\n"
    for tt in uses:
        nm = tt.replace("<","").replace(">","").replace(" ","").replace("x","x")
        hdr += "declare void @use_%s(%s)\n" % (nm, tt)
    return hdr + "define void @f(%s) {\n" % ", ".join("%s %s" % (t, p) for p in params) + "\n".join(body) + "\n" + "\n".join(sinks) + "\n}\n"

def main():
    seed0 = int(sys.argv[1]); N = int(sys.argv[2])
    for s in range(seed0, seed0 + N):
        rng = random.Random(s)
        ir = gen(rng)
        open("/tmp/w/f.ll", "w").write(ir)
        r = subprocess.run(["opt", "-S", "-passes=bdce", "/tmp/w/f.ll", "-o", "/tmp/w/f.out.ll"], capture_output=True, text=True)
        if r.returncode != 0:
            print("=== SEED %d: OPT ISSUE ===\n%s\n%s" % (s, ir, r.stderr[:1500])); return
        r = subprocess.run(["alive-tv", "/tmp/w/f.ll", "/tmp/w/f.out.ll"], capture_output=True, text=True)
        if "Transformation seems to be correct" not in r.stdout:
            print("=== SEED %d: PROBLEM ===\n%s--- OUTPUT ---\n%s\n%s" % (s, ir, open("/tmp/w/f.out.ll").read(), r.stdout[-2500:]))
            return
    print("no issues in %d..%d" % (seed0, seed0+N-1))

main()
